import pandas as pd
import numpy as np
import json
import math

# Load Data
df = pd.read_csv('/app/benchmark/data.csv')

# Preprocessing
df['over_int'] = df['over'].apply(math.floor)
df['is_valid_ball'] = (df['wide'] == 0) & (df['noballs'] == 0)
df['bowler_runs'] = df['runs_of_bat'] + df['wide'] + df['noballs']
df['is_boundary'] = df['runs_of_bat'].isin([4, 6])
df['is_dot'] = (df['runs_of_bat'] == 0) & (df['extras'] == 0)
df['is_wicket'] = df['wicket_type'].notna() & (df['wicket_type'] != '')
bowler_wickets = ['bowled', 'caught', 'lbw', 'stumped', 'caught and bowled', 'hit wicket']
df['is_bowler_wicket'] = df['wicket_type'].isin(bowler_wickets)

total_matches = df['match_no'].nunique()
total_deliveries = len(df)
total_runs = df['runs_of_bat'].sum() + df['extras'].sum()
total_wickets = df['is_wicket'].sum()
valid_balls = df['is_valid_ball'].sum()
total_overs = valid_balls / 6.0

# 1. KPIs
avg_runs_per_over = total_runs / total_overs if total_overs else 0
boundary_pct = (df['is_boundary'].sum() / total_deliveries) * 100
dot_ball_pct = (df['is_dot'].sum() / total_deliveries) * 100
extras_per_match = df['extras'].sum() / total_matches
wickets_per_match = total_wickets / total_matches

# 2. Batting Analysis
batter_stats = df.groupby('striker').agg(
    runs=('runs_of_bat', 'sum'),
    balls=('is_valid_ball', 'sum'),
    fours=('runs_of_bat', lambda x: (x == 4).sum()),
    sixes=('runs_of_bat', lambda x: (x == 6).sum())
).reset_index()
batter_stats['strike_rate'] = (batter_stats['runs'] / batter_stats['balls'] * 100).fillna(0)
top_batters = batter_stats.sort_values(by='runs', ascending=False).head(10)

def get_phase(over):
    if over < 6: return 'Powerplay (0-5)'
    elif over < 15: return 'Middle Overs (6-14)'
    else: return 'Death Overs (15-19)'
df['phase'] = df['over_int'].apply(get_phase)

phase_stats = df.groupby('phase').agg(
    runs=('runs_of_bat', 'sum'),
    balls=('is_valid_ball', 'sum'),
    boundaries=('is_boundary', 'sum'),
    dots=('is_dot', 'sum')
).reset_index()
phase_stats['strike_rate'] = (phase_stats['runs'] / phase_stats['balls'] * 100).fillna(0)

# 3. Bowling Analysis
bowler_stats = df.groupby('bowler').agg(
    wickets=('is_bowler_wicket', 'sum'),
    runs_conceded=('bowler_runs', 'sum'),
    balls_bowled=('is_valid_ball', 'sum'),
    dots=('is_dot', 'sum')
).reset_index()
bowler_stats['overs'] = bowler_stats['balls_bowled'] / 6.0
bowler_stats['economy'] = (bowler_stats['runs_conceded'] / bowler_stats['overs']).fillna(0)
bowler_stats['dot_pct'] = (bowler_stats['dots'] / bowler_stats['balls_bowled'] * 100).fillna(0)
top_bowlers = bowler_stats[bowler_stats['overs'] >= 2].sort_values(by=['wickets', 'economy'], ascending=[False, True]).head(10)

dismissal_types = df[df['is_wicket']]['wicket_type'].value_counts().reset_index()
dismissal_types.columns = ['type', 'count']

# 4. Team Analysis
team_runs = df.groupby(['match_no', 'batting_team'])['runs_of_bat'].sum() + df.groupby(['match_no', 'batting_team'])['extras'].sum()
team_runs = team_runs.reset_index().rename(columns={0: 'total_runs'})
avg_runs_team = team_runs.groupby('batting_team')['total_runs'].mean().reset_index()

team_extras = df.groupby('bowling_team')['extras'].sum().reset_index()
team_extras['extras_per_match'] = team_extras['extras'] / df.groupby('bowling_team')['match_no'].nunique().values

# 5. Venue Insights
venue_stats = df.groupby(['venue', 'match_no', 'innings']).agg(
    runs=('runs_of_bat', 'sum'),
    extras=('extras', 'sum')
).reset_index()
venue_stats['total'] = venue_stats['runs'] + venue_stats['extras']

venue_avg = venue_stats.groupby('venue')['total'].mean().reset_index()

# Prepare Match Winners for Batting First vs Chasing
match_results = []
for match in df['match_no'].unique():
    m_df = venue_stats[venue_stats['match_no'] == match]
    if len(m_df) == 2:
        in1 = m_df[m_df['innings'] == 1]['total'].values[0]
        in2 = m_df[m_df['innings'] == 2]['total'].values[0]
        if in1 > in2:
            match_results.append({'venue': m_df['venue'].values[0], 'winner': 'Batting First'})
        elif in2 > in1:
            match_results.append({'venue': m_df['venue'].values[0], 'winner': 'Chasing'})

res_df = pd.DataFrame(match_results)
if not res_df.empty:
    win_toss = res_df['winner'].value_counts().reset_index()
    win_toss.columns = ['winner', 'count']
else:
    win_toss = pd.DataFrame([{'winner': 'Batting First', 'count': 0}, {'winner': 'Chasing', 'count': 0}])

# HTML Generation via Jinja/String Format
