            text-align: center;
            padding: 2rem;
            color: var(--text-muted);
            font-size: 0.875rem;
            margin-top: 3rem;
            border-top: 1px solid var(--border);
        }}
    </style>
</head>
<body>
    <div class="container">
        <header>
            <h1>IPL 2026 Analytics Report</h1>
            <div class="subtitle">Comprehensive Ball-by-Ball Analysis</div>
        </header>

        <h2>Tournament Overview & Match Summary</h2>
        <p>A statistical summary of the IPL 2026 season across {total_matches} matches.</p>

