            type: 'doughnut',
            data: {{
                labels: dismissalLabels,
                datasets: [{{
                    data: dismissalCounts,
                    backgroundColor: ['#1e3a8a', '#3b82f6', '#60a5fa', '#93c5fd', '#bfdbfe']
                }}]
            }},
            options: {{
                plugins: {{ title: {{ display: true, text: 'Dismissal Types Breakdown' }} }}
            }}
