        const teamRuns = {json.dumps(avg_runs_team['total_runs'].tolist())};

        new Chart(document.getElementById('teamRunsChart'), {{
            type: 'bar',
            data: {{
                labels: teamLabels,
                datasets: [{{
                    label: 'Average Runs per Innings',
                    data: teamRuns,
                    backgroundColor: '#10b981',
                    borderRadius: 4
                }}]
            }},
            options: {{
                plugins: {{ title: {{ display: true, text: 'Team Batting Performance' }} }}
            }}
        }});

        const teamExtrasLabels = {json.dumps(team_extras['bowling_team'].tolist())};
        const teamExtrasCounts = {json.dumps(team_extras['extras_per_match'].tolist())};

        new Chart(document.getElementById('teamExtrasChart'), {{
            type: 'bar',
            data: {{
                labels: teamExtrasLabels,
                datasets: [{{
                    label: 'Extras Conceded per Match',
                    data: teamExtrasCounts,
                    backgroundColor: '#ef4444',
                    borderRadius: 4
                }}]
            }},
            options: {{
                plugins: {{ title: {{ display: true, text: 'Bowling Discipline (Extras)' }} }}
            }}
        }});

        const venueLabels = {json.dumps(venue_avg['venue'].tolist())};
        const venueScores = {json.dumps(venue_avg['total'].tolist())};

        new Chart(document.getElementById('venueScoreChart'), {{
            type: 'bar',
            data: {{
                labels: venueLabels,
                datasets: [{{
                    label: 'Avg Innings Score',
                    data: venueScores,
                    backgroundColor: '#8b5cf6',
                    borderRadius: 4
                }}]
            }},
            options: {{
                indexAxis: 'y',
                plugins: {{ title: {{ display: true, text: 'Average Score by Venue' }} }}
            }}
        }});

        const winLabels = {json.dumps(win_toss['winner'].tolist())};
        const winCounts = {json.dumps(win_toss['count'].tolist())};

        new Chart(document.getElementById('winTossChart'), {{
            type: 'pie',
            data: {{
                labels: winLabels,
                datasets: [{{
                    data: winCounts,
                    backgroundColor: ['#f59e0b', '#10b981']
                }}]
            }},
            options: {{
                plugins: {{ title: {{ display: true, text: 'Batting First vs Chasing Success' }} }}
            }}
        }});
    </script>
</body>
</html>
"""

with open('/app/output/final_report.html', 'w') as f:
    f.write(html_template)
print("Report generated successfully.")
